// Шукаємо JSON-блок (від { до }) у відповіді бота
const match = $json.output.match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error('Не вдалося знайти JSON у відповіді бота');
}
const parsed = JSON.parse(match[0]);

for (const k of ['project_name', 'manager_username', 'email', 'server_type']) {
  if (!parsed[k]) throw new Error('Відсутній параметр: ' + k);
}

// Паролі генеруються на самому сервері (див. Deploy Backend), тут їх більше немає
delete parsed.admin_username;
parsed.chat_space = $json.chat_space;

return [{ json: parsed }];

const sd = $getWorkflowStaticData('global');
sd.memEpochs = sd.memEpochs || {};
const space = $('Вебхук: повідомлення з чату').first().json.body.chat.messagePayload.space.name;
const id = String(space).split('/').pop();
sd.memEpochs[id] = (sd.memEpochs[id] || 0) + 1;
return [{ json: { chat_space: space, epoch: sd.memEpochs[id] } }];

const sd = $getWorkflowStaticData('global');
sd.memEpochs = sd.memEpochs || {};
const item = $input.first().json;
const msg = item.body.chat.messagePayload.message;
const space = String(item.body.chat.messagePayload.space.name).split('/').pop();
const txt = String(msg.text || '').trim();
if (/^\/reset\b/i.test(txt)) {
  sd.memEpochs[space] = (sd.memEpochs[space] || 0) + 1;
  const rest = txt.replace(/^\/reset\b/i, '').trim();
  msg.text = rest || '[СЕРВІС] Пам\'ять діалогу скинуто. Підтверди користувачу одним коротким реченням, що можна продовжувати.';
}
const day = DateTime.now().setZone('Europe/Kyiv').toFormat('yyyyLLdd');
return [{ json: Object.assign({}, item, { session_key: space + '_v4_' + day + '_' + (sd.memEpochs[space] || 0) }) }];
